  /* ---------- финансы ---------- */
  function irr(flows){
    function npv(r){ return flows.reduce(function(s, f, i){ return s + f / Math.pow(1 + r, i); }, 0); }
    var lo = -0.99, hi = 10, a = npv(lo), b = npv(hi); if(a * b > 0) return null;
    for(var i = 0; i < 200; i++){ var m = (lo + hi) / 2, v = npv(m); if(a * v <= 0){ hi = m; b = v; } else { lo = m; a = v; } }
    return (lo + hi) / 2;
  }
