          var A = i ? S * i / (1 - Math.pow(1 + i, -n)) : S / n;
          for(var k = 0; k < n; k++){
            var d = new Date(d0.getFullYear(), d0.getMonth() + k, d0.getDate()), pr = left * i, body = p.kind === 'diff' ? S / n : A - pr, pay = body + pr;
            if(k === n - 1){ body = left; pay = body + pr; }
            left -= body; paid += pay;
            out.push({ '№':k + 1, 'Дата':ruDateStr(d), 'Платёж':r2(pay), 'Проценты':r2(pr), 'Основной долг':r2(body), 'Остаток долга':r2(Math.max(0, left)) });
          }
          ctx.info = 'Переплата: ' + money(paid - S) + ' руб., ' + (p.kind === 'diff' ? 'первый платёж ' + money(out[0]['Платёж']) : 'платёж ' + money(A)) + ' руб.'; ctx.table(ctx.name, out); return out;
