          function score(v, key, lowIsGood){ var s = cl.map(function(x){ return x[key]; }).sort(function(a, b){ return a - b; }), i = s.indexOf(v) / Math.max(1, s.length - 1); var sc = i < 1 / 3 ? 1 : (i < 2 / 3 ? 2 : 3); return lowIsGood ? 4 - sc : sc; }
